import { CommonPoolController } from "approot/global/controllers/common.pool.controller";
import { RegistryBasedComponentTemplate, RegistryBtn, IRegistryController, RegistryInfo } from "approot/global/components/registry/registry.model";
import { LongWorkService } from "approot/global/providers/uikit.dialogs";

class AdminPoolController extends CommonPoolController {

	/*@ngInject*/
	constructor(
		$scope,
		private $location: ng.ILocationService,
		$q: ng.IQService,
		$longWork: LongWorkService,
		$http: ng.IHttpService,
		$uibModal: ng.ui.bootstrap.IModalService,
		language: any
	) {
		super($scope, $q, $longWork, $http, $uibModal, language)
	}

	initTitle() {
		this.$scope.$parent.page = {
			title: this.language.FilterUsers.kFreeStudentsList
		};
	}

	getButtons(): RegistryBtn[] {
		return [
			{
				title: this.language.Generic.PoolStudents.kOutOfSystem,
				action: () => this.$location.path("/outofsystem/"),
			}
		]
	}
}

class OutOfSystemStudentsController {
	public registryInfo: RegistryInfo;
	public controller: IRegistryController;

	/*@ngInject*/
	constructor($scope,	$location: ng.ILocationService,	language: any ) {

		$scope.$parent.page = {
			title: language.Generic.FilterUsers.kStudentsOutOfSystem
		};

		this.registryInfo = {
			url:  "/webapi/movement/outofsystemstudents/registry",
			filtersUrl: "/webapi/movement/outofsystemstudents/registry/filter",
			buttons: [{
				title: language.Generic.PoolStudents.kInSystem,
				action: () => $location.path("/pool/"),
			}],
			linkButtons: []
		};
	}
}

export const AdminPoolComponent = {
	controller: AdminPoolController,
	controllerAs: "ctrl",
	template: RegistryBasedComponentTemplate
}

export const OutOfSystemStudentsComponent = {
	controller: OutOfSystemStudentsController,
	controllerAs: "ctrl",
	template: RegistryBasedComponentTemplate
}


