export default class SearchSource {
	constructor(settings, $http) {
		this.$http = $http;
		for (let searchItemKey in settings) {
			if (settings.hasOwnProperty(searchItemKey)) {
				this.appendSearchItem(searchItemKey, settings[searchItemKey]);
			}
		}
	}

	appendSearchItem(key, itemSettings) {
		const defSettings = {
			map: (item) => item,
			minChars: 3,
			searchParam: "name",
			emptyChoiceItem: null
		}

		let settings = {};
		angular.extend(settings, defSettings, itemSettings);
		const ctx = this;

		const itemCtx = {
			items: [],
			search: (text) => {
				if (!text || text.length < settings.minChars) {
					return;
				}
				itemCtx.items = [{ name: 'Поиск...' }];

				let params = angular.extend({}, settings.params);
				params[settings.searchParam] = text;

				//распаковка параметров из функций
				for (var property in params) {
					if (params.hasOwnProperty(property)) {
						let propValue = params[property];
						if (typeof (propValue) == "function") {
							params[property] = propValue();
						}
					}
				}

				let url = settings.url;
				if (typeof (url) === "function") {
					url = url();
				}
				ctx.$http.get(url, { params: params })
					.then((response) => {
						const emptyChoiceItems = settings.emptyChoiceItem == null ? [] : [settings.emptyChoiceItem];
						if (!response.data.length) {
							itemCtx.items = [{ name: 'Совпадений не найдено' }].concat(emptyChoiceItems);
						} else {
							itemCtx.items =  emptyChoiceItems.concat(_.map(response.data, settings.map));
						}
					})
					.catch((response) => {
						$alerts.error(response.data.message, response.data.details);
					});
			}
		}

		this[key] = itemCtx;
	}
}


